-- STAGING ONLY 482: every Job Card OP is retained; description is first OP header only; every Pre Delivery is 1.5 hours.
BEGIN;SET LOCAL statement_timeout='180s';SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-482-jobcard-header-only-all-lines',0));
DO $g$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827031000' AND name='481_navision_linked_vehicle_refresh') OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$' AND version>'20260827031000') OR (SELECT count(*) FROM public.vehicles WHERE id='99518513-5293-5619-a06e-9b4323754838'::uuid AND stock_number_normalized='13000776' AND job_card_number='J139125495' AND deleted_at IS NULL)<>1 OR (SELECT count(*) FROM public.pdc_authenticated_email_operation_lines WHERE vehicle_id='99518513-5293-5619-a06e-9b4323754838'::uuid AND source_hash='141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96')<>22 OR EXISTS(SELECT 1 FROM public.workshop_bookings WHERE vehicle_id='99518513-5293-5619-a06e-9b4323754838'::uuid AND deleted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.pdc_supervised_rule_versions WHERE version_id='12aad1e7-c5da-4bd7-9145-80133dfdbef1'::uuid AND family_id='6620c922-1f16-4b17-8e02-a5402c15a5f7'::uuid AND version_no=1 AND work_key='fitting' AND estimated_hours IS NULL) OR coalesce((SELECT enabled FROM public.pdc_email_monitor_pilot WHERE singleton),false) OR EXISTS(SELECT 1 FROM public.monitored_mailboxes WHERE active) OR EXISTS(SELECT 1 FROM public.pdc_monitor_stage_activation_writers WHERE active AND revoked_at IS NULL) THEN RAISE EXCEPTION 'PDC_482_TARGET_HEAD_SCOPE_OR_CONTAINMENT_MISMATCH' USING errcode='55000';END IF;END $g$;
CREATE TABLE public.pdc_owner_jobcard_import_rules_482(rule_key text PRIMARY KEY CHECK(rule_key IN('first-op-header-only','all-pre-delivery-1.5-hours','every-jobcard-op-visible')),rule_text text NOT NULL,created_by uuid NOT NULL CHECK(created_by='8a83b715-8d79-4b0e-95b2-02b55da6e8d7'::uuid),created_by_email text NOT NULL CHECK(created_by_email='craig.watson@broometoyota.com.au'),created_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_owner_jobcard_import_rules_482 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_owner_jobcard_import_rules_482 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_owner_jobcard_import_rules_482(rule_key,rule_text,created_by,created_by_email) VALUES('first-op-header-only','When importing an email Job Card operation, use only the first numbered OP header line as its description; never append CN, SN, Notes, specification, vehicle or continuation detail underneath it.','8a83b715-8d79-4b0e-95b2-02b55da6e8d7','craig.watson@broometoyota.com.au'),('all-pre-delivery-1.5-hours','Every kind of Pre Delivery uses the Craig-approved standard estimate of 1.50 hours, regardless of the source estimate printed on the Job Card.','8a83b715-8d79-4b0e-95b2-02b55da6e8d7','craig.watson@broometoyota.com.au'),('every-jobcard-op-visible','Every genuine numbered Job Card OP must be retained and shown on the Board; operations without an approved station mapping remain visible under Unallocated - mapping review.','8a83b715-8d79-4b0e-95b2-02b55da6e8d7','craig.watson@broometoyota.com.au');
DO $rule$ DECLARE new_version uuid:=extensions.uuid_generate_v5('6620c922-1f16-4b17-8e02-a5402c15a5f7'::uuid,'pre-delivery-all-kinds-1.5-hours-v2');BEGIN INSERT INTO public.pdc_supervised_rule_versions(version_id,family_id,version_no,predecessor_version_id,original_telegram_instruction,authorized_by,authorized_by_email,proposed_by,effective_from,priority,confidence,match_kind,operation_code,normalized_description,phrase_category,work_key,estimated_hours,cost_ex_gst,sell_ex_gst,gst_percent,currency) VALUES(new_version,'6620c922-1f16-4b17-8e02-a5402c15a5f7',2,'12aad1e7-c5da-4bd7-9145-80133dfdbef1','Craig: Pre Delivery of all kinds are 1.5 hours standard.','8a83b715-8d79-4b0e-95b2-02b55da6e8d7','craig.watson@broometoyota.com.au','8a83b715-8d79-4b0e-95b2-02b55da6e8d7',clock_timestamp(),9800,1,'phrase',null,null,'pre_delivery','fitting',1.50,null,null,null,null);INSERT INTO public.pdc_supervised_rule_aliases(version_id,alias) VALUES(new_version,'pre delivery');INSERT INTO public.pdc_supervised_rule_examples(version_id,example_kind,example_text,source_stock) VALUES(new_version,'positive','Pre-Delivery (Commercial)','13000776'),(new_version,'positive','Pre Delivery Inspection',null),(new_version,'positive','Complete Pre-Delivery Inspection',null);INSERT INTO public.pdc_supervised_rule_events(family_id,version_id,event_kind,reason,actor_id,actor_email) VALUES('6620c922-1f16-4b17-8e02-a5402c15a5f7','12aad1e7-c5da-4bd7-9145-80133dfdbef1','superseded','Craig standardised every kind of Pre Delivery at 1.50 hours.','8a83b715-8d79-4b0e-95b2-02b55da6e8d7','craig.watson@broometoyota.com.au'),('6620c922-1f16-4b17-8e02-a5402c15a5f7',new_version,'proposed','Craig supplied durable Pre Delivery standard.','8a83b715-8d79-4b0e-95b2-02b55da6e8d7','craig.watson@broometoyota.com.au'),('6620c922-1f16-4b17-8e02-a5402c15a5f7',new_version,'activated','Craig supplied durable Pre Delivery standard.','8a83b715-8d79-4b0e-95b2-02b55da6e8d7','craig.watson@broometoyota.com.au');END $rule$;
CREATE TEMP TABLE pdc482_manifest ON COMMIT DROP AS SELECT (x->>'source_row_no')::integer source_row_no,x->>'operation_no' operation_no,x->>'work_key' work_key,x->>'description' description,CASE WHEN jsonb_typeof(x->'estimated_hours')='number' THEN (x->>'estimated_hours')::numeric ELSE NULL END estimated_hours,x->>'estimated_hours_source' estimated_hours_source FROM jsonb_array_elements($ops$[{"source_row_no":1,"operation_no":"OP1","work_key":"owner_supplied_document","description":"COMPLEMENTARY FULL TANK OF FUEL","estimated_hours":0.0,"estimated_hours_source":"job_card"},{"source_row_no":2,"operation_no":"OP2","work_key":"fitting","description":"Pre-Delivery (Commercial)","estimated_hours":1.5,"estimated_hours_source":"job_card"},{"source_row_no":3,"operation_no":"OP3","work_key":"fitting","description":"Steel Bull Bar - Commercial","estimated_hours":5.18,"estimated_hours_source":"job_card"},{"source_row_no":4,"operation_no":"OP4","work_key":"owner_supplied_document","description":"Tow Bar [For 2550mm/2100mm/1800mm Tray Body] with Small Round Plug (Long Tongue)","estimated_hours":1.58,"estimated_hours_source":"job_card"},{"source_row_no":5,"operation_no":"OP5","work_key":"owner_supplied_document","description":"Wheel Nut Indicator Set","estimated_hours":0.25,"estimated_hours_source":"job_card"},{"source_row_no":6,"operation_no":"OP6","work_key":"owner_supplied_document","description":"1.2m Whip Flag with Spring Base to Suit Minebars - No Light","estimated_hours":0.1,"estimated_hours_source":"job_card"},{"source_row_no":7,"operation_no":"OP7","work_key":"owner_supplied_document","description":"1.5 Kg Fire Extinuisher to LHF floor","estimated_hours":0.5,"estimated_hours_source":"job_card"},{"source_row_no":8,"operation_no":"OP8","work_key":"owner_supplied_document","description":"Battery Isolator with Locksafe Cover mounted Under Bonnet - Hilux","estimated_hours":0.3,"estimated_hours_source":"job_card"},{"source_row_no":9,"operation_no":"OP9","work_key":"owner_supplied_document","description":"firstaid kit big","estimated_hours":0.0,"estimated_hours_source":"job_card"},{"source_row_no":10,"operation_no":"OP10","work_key":"owner_supplied_document","description":"Headlamps Auto On & Hand Brake OFF Alarm Combo - DYNAMCO - Hilux","estimated_hours":1.5,"estimated_hours_source":"job_card"},{"source_row_no":11,"operation_no":"OP11","work_key":"fabrication","description":"MINE BAR WITH FORWARD FACING INDICATORS, DUAL SOUND REVERSE BUZZER","estimated_hours":3.5,"estimated_hours_source":"job_card"},{"source_row_no":12,"operation_no":"OP12","work_key":"fitting","description":"SUB - MMT 2 Row Canvas Seat Covers","estimated_hours":0.0,"estimated_hours_source":"job_card"},{"source_row_no":13,"operation_no":"OP13","work_key":"fabrication","description":"PMB002 -Dual Cab ROPS Certified HD Steel Tray 1850mm x 1900mm (232kg)","estimated_hours":0.0,"estimated_hours_source":"job_card"},{"source_row_no":14,"operation_no":"OP14","work_key":"tyre","description":"Spare Tyre Holder To Suit PMB Cab Rack Each","estimated_hours":0.0,"estimated_hours_source":"job_card"},{"source_row_no":15,"operation_no":"OP15","work_key":"owner_supplied_document","description":"Certified Mesh Cab Rack Barrier Rated To 60kg With Certification Plate","estimated_hours":0.0,"estimated_hours_source":"job_card"},{"source_row_no":16,"operation_no":"OP16","work_key":"owner_supplied_document","description":"Reverse Camera Relocation Bracket Required For All Vehicles With Standard Reverse","estimated_hours":0.0,"estimated_hours_source":"job_card"},{"source_row_no":17,"operation_no":"OP17","work_key":"owner_supplied_document","description":"Wheel Chock's & Holder Mounted","estimated_hours":null,"estimated_hours_source":"owner_supplied_document_unknown"},{"source_row_no":18,"operation_no":"OP18","work_key":"owner_supplied_document","description":"Mount Safety Triangles & Holder to L/H side of Headboard or Cargo area","estimated_hours":0.3,"estimated_hours_source":"job_card"},{"source_row_no":19,"operation_no":"OP19","work_key":"tyre","description":"Hilux Additional Spare 7.5x17 Steel Rim 265/65R17 Factory Tyre","estimated_hours":null,"estimated_hours_source":"owner_supplied_document_unknown"},{"source_row_no":20,"operation_no":"OP20","work_key":"owner_supplied_document","description":"SUB CALL SIGNS","estimated_hours":null,"estimated_hours_source":"owner_supplied_document_unknown"},{"source_row_no":21,"operation_no":"OP21","work_key":"sublet","description":"Reflective Stripes - Yellow","estimated_hours":null,"estimated_hours_source":"owner_supplied_document_unknown"},{"source_row_no":22,"operation_no":"OP22","work_key":"owner_supplied_document","description":"GME XRS-370c with PMB Standard Aerial","estimated_hours":null,"estimated_hours_source":"owner_supplied_document_unknown"}]$ops$::jsonb)x;
DO $m$ BEGIN IF (SELECT count(*) FROM pdc482_manifest)<>22 OR (SELECT count(*) FROM pdc482_manifest WHERE estimated_hours=0)<>7 OR (SELECT count(*) FROM pdc482_manifest WHERE estimated_hours IS NULL)<>5 OR (SELECT count(*) FROM pdc482_manifest WHERE work_key='owner_supplied_document')<>14 OR (SELECT sum(estimated_hours) FROM pdc482_manifest)<>14.71 OR NOT EXISTS(SELECT 1 FROM pdc482_manifest WHERE operation_no='OP2' AND description='Pre-Delivery (Commercial)' AND estimated_hours=1.50 AND estimated_hours_source='job_card') OR EXISTS(SELECT 1 FROM pdc482_manifest WHERE description~'(^| )(CN|SN) ' OR description ILIKE '%Notes :%') OR (SELECT array_agg(operation_no ORDER BY source_row_no) FROM pdc482_manifest)<>ARRAY['OP1','OP2','OP3','OP4','OP5','OP6','OP7','OP8','OP9','OP10','OP11','OP12','OP13','OP14','OP15','OP16','OP17','OP18','OP19','OP20','OP21','OP22'] THEN RAISE EXCEPTION 'PDC_482_HEADER_MANIFEST_INVALID';END IF;END $m$;
CREATE TEMP TABLE pdc482_adjustment_before ON COMMIT DROP AS SELECT a.* FROM public.vehicle_workshop_line_adjustments a WHERE a.vehicle_id='99518513-5293-5619-a06e-9b4323754838'::uuid;
INSERT INTO public.vehicle_workshop_line_adjustments(adjustment_id,vehicle_id,line_key,source_kind,stage_code,description,estimated_hours,active,version,created_by,created_at,updated_by,updated_at,operation_code,display_order,manual_assignment_locked,correction_origin,source_operation_line_id,job_card_number) SELECT gen_random_uuid(),l.vehicle_id,'source:'||l.operation_line_id::text,'source',CASE m.work_key WHEN 'bus4x4' THEN 'BUS_4X4' WHEN 'tint' THEN 'TINT' WHEN 'hoist' THEN 'HOIST' WHEN 'fitting' THEN 'FITTING' WHEN 'fabrication' THEN 'FABRICATION' WHEN 'electrical' THEN 'ELECTRICAL' WHEN 'tyre' THEN 'TYRE' WHEN 'pitInspection' THEN 'PIT_INSPECTION' WHEN 'PARTS' THEN 'PARTS' WHEN 'sublet' THEN 'SUBLET' ELSE 'OWNER_SUPPLIED_DOCUMENT' END,m.description,m.estimated_hours,true,1,'8a83b715-8d79-4b0e-95b2-02b55da6e8d7',clock_timestamp(),'8a83b715-8d79-4b0e-95b2-02b55da6e8d7',clock_timestamp(),m.operation_no,m.source_row_no,false,null,l.operation_line_id,'J139125495' FROM pdc482_manifest m JOIN public.pdc_authenticated_email_operation_lines l ON l.source_hash='141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96' AND l.operation_no=m.operation_no ON CONFLICT(vehicle_id,line_key) DO UPDATE SET description=excluded.description,estimated_hours=CASE WHEN excluded.operation_code='OP2' THEN 1.50 ELSE public.vehicle_workshop_line_adjustments.estimated_hours END,active=true,version=public.vehicle_workshop_line_adjustments.version+1,updated_by=excluded.updated_by,updated_at=excluded.updated_at,operation_code=excluded.operation_code,display_order=excluded.display_order,source_operation_line_id=excluded.source_operation_line_id,job_card_number=excluded.job_card_number;
INSERT INTO public.audit_events(action,table_name,row_id,vehicle_id,actor_id,actor_email,before_data,after_data,metadata) SELECT (CASE WHEN b.adjustment_id IS NULL THEN 'insert' ELSE 'update' END)::public.audit_action,'vehicle_workshop_line_adjustments',a.adjustment_id,a.vehicle_id,'8a83b715-8d79-4b0e-95b2-02b55da6e8d7','craig.watson@broometoyota.com.au',to_jsonb(b),to_jsonb(a),jsonb_build_object('source','jobcard-header-only-rule-482','operation_no',a.operation_code,'first_op_header_only',true,'pre_delivery_standard_hours',CASE WHEN a.operation_code='OP2' THEN 1.50 ELSE null END,'all_22_effective_lines_visible',true,'preexisting_stage_and_hours_preserved',b.adjustment_id IS NOT NULL) FROM public.vehicle_workshop_line_adjustments a LEFT JOIN pdc482_adjustment_before b USING(adjustment_id) WHERE a.vehicle_id='99518513-5293-5619-a06e-9b4323754838'::uuid AND (b.adjustment_id IS NULL OR to_jsonb(a) IS DISTINCT FROM to_jsonb(b));
INSERT INTO public.pdc_email_operation_mapping_reviews_478(receipt_id,operation_line_id,operation_no,reason) SELECT 'e7571359-c84c-493f-8376-d8384ea70b6f',l.operation_line_id,l.operation_no,'station mapping is not established by an existing Craig-approved durable rule' FROM pdc482_manifest m JOIN public.pdc_authenticated_email_operation_lines l ON l.source_hash='141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96' AND l.operation_no=m.operation_no WHERE m.work_key='owner_supplied_document' ON CONFLICT(operation_line_id) DO NOTHING;
CREATE TABLE public.pdc_uid632_header_only_receipts_482(receipt_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action_key text NOT NULL UNIQUE CHECK(action_key='uid632-header-only-all-22-482'),vehicle_id uuid NOT NULL REFERENCES public.vehicles(id) ON DELETE RESTRICT,source_hash text NOT NULL CHECK(source_hash='141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96'),predecessor_receipt_id uuid NOT NULL REFERENCES public.pdc_uid632_operation_completeness_receipts_479(receipt_id) ON DELETE RESTRICT,manifest_sha256 text NOT NULL CHECK(manifest_sha256='3a59213d5120954eddd3cbc049b3eecde65e1f72f315b08d474f34ef3fed3468'),operation_count integer NOT NULL CHECK(operation_count=22),mapped_count integer NOT NULL CHECK(mapped_count=8),unallocated_visible_count integer NOT NULL CHECK(unallocated_visible_count=14),explicit_zero_count integer NOT NULL CHECK(explicit_zero_count=7),unknown_hours_count integer NOT NULL CHECK(unknown_hours_count=5),known_hours_sum numeric(10,2) NOT NULL CHECK(known_hours_sum=14.71),pre_delivery_hours numeric(4,2) NOT NULL CHECK(pre_delivery_hours=1.50),header_only boolean NOT NULL CHECK(header_only),operation_manifest jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_uid632_header_only_receipts_482 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_uid632_header_only_receipts_482 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_uid632_header_only_receipts_482(action_key,vehicle_id,source_hash,predecessor_receipt_id,manifest_sha256,operation_count,mapped_count,unallocated_visible_count,explicit_zero_count,unknown_hours_count,known_hours_sum,pre_delivery_hours,header_only,operation_manifest) SELECT 'uid632-header-only-all-22-482','99518513-5293-5619-a06e-9b4323754838','141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96',(SELECT receipt_id FROM public.pdc_uid632_operation_completeness_receipts_479 WHERE action_key='uid632-complete-operations-479'),'3a59213d5120954eddd3cbc049b3eecde65e1f72f315b08d474f34ef3fed3468',22,8,14,7,5,14.71,1.50,true,jsonb_agg(jsonb_build_object('source_row_no',source_row_no,'operation_no',operation_no,'work_key',work_key,'description',description,'estimated_hours',estimated_hours,'estimated_hours_source',estimated_hours_source) ORDER BY source_row_no) FROM pdc482_manifest;
CREATE TABLE public.pdc_email_header_only_runtime_binding_482(binding_key text PRIMARY KEY CHECK(binding_key='paused-header-only-all-operations-runtime-482'),runtime_processor_sha256 text NOT NULL CHECK(runtime_processor_sha256='dfd493de92a86b92b2eea72763d5a067ac1092c4ddda1a2e29af39e4713adfba'),runtime_client_sha256 text NOT NULL CHECK(runtime_client_sha256='c1951aedc00e7ade5b78f2038471423524e19dd27a59401ec87b6bd3eee88b22'),scheduler_sha256 text NOT NULL CHECK(scheduler_sha256='2738643248f097c13fef188150a41a8483ce782744c403b3a2951033473e94b9'),regression_test_sha256 text NOT NULL CHECK(regression_test_sha256='423c3790169b113f53510f1f35e034f7c024573c639de099443dd4a8e4defc8e'),fixture_sha256 text NOT NULL CHECK(fixture_sha256='85a83a1f0f9186e68241eb7015c1b0fac31a3201a94daaebd36794c595995342'),automatic_activation_permitted boolean NOT NULL CHECK(NOT automatic_activation_permitted),bound_by uuid NOT NULL CHECK(bound_by='8a83b715-8d79-4b0e-95b2-02b55da6e8d7'),bound_by_email text NOT NULL CHECK(bound_by_email='craig.watson@broometoyota.com.au'),bound_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_email_header_only_runtime_binding_482 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_email_header_only_runtime_binding_482 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_email_header_only_runtime_binding_482(binding_key,runtime_processor_sha256,runtime_client_sha256,scheduler_sha256,regression_test_sha256,fixture_sha256,automatic_activation_permitted,bound_by,bound_by_email) VALUES('paused-header-only-all-operations-runtime-482','dfd493de92a86b92b2eea72763d5a067ac1092c4ddda1a2e29af39e4713adfba','c1951aedc00e7ade5b78f2038471423524e19dd27a59401ec87b6bd3eee88b22','2738643248f097c13fef188150a41a8483ce782744c403b3a2951033473e94b9','423c3790169b113f53510f1f35e034f7c024573c639de099443dd4a8e4defc8e','85a83a1f0f9186e68241eb7015c1b0fac31a3201a94daaebd36794c595995342',false,'8a83b715-8d79-4b0e-95b2-02b55da6e8d7','craig.watson@broometoyota.com.au');
UPDATE public.pdc_email_vehicle_revision SET revision=revision+1,updated_at=clock_timestamp() WHERE singleton;
DO $post$ BEGIN IF (SELECT count(*) FROM public.pdc_authenticated_email_operation_lines WHERE vehicle_id='99518513-5293-5619-a06e-9b4323754838' AND source_hash='141354ac4a92cb01c031ee782450e56451061d7ba2f68b8fb79aca2a3d503a96')<>22 OR (SELECT count(*) FROM public.vehicle_workshop_line_adjustments WHERE vehicle_id='99518513-5293-5619-a06e-9b4323754838' AND active AND source_kind='source' AND source_operation_line_id IS NOT NULL)<>22 OR (SELECT count(*) FROM public.vehicle_workshop_line_adjustments WHERE vehicle_id='99518513-5293-5619-a06e-9b4323754838' AND active AND stage_code='OWNER_SUPPLIED_DOCUMENT')<>14 OR NOT EXISTS(SELECT 1 FROM public.vehicle_workshop_line_adjustments WHERE vehicle_id='99518513-5293-5619-a06e-9b4323754838' AND operation_code='OP2' AND description='Pre-Delivery (Commercial)' AND estimated_hours=1.50) OR EXISTS(SELECT 1 FROM public.vehicle_workshop_line_adjustments WHERE vehicle_id='99518513-5293-5619-a06e-9b4323754838' AND (description~'(^| )(CN|SN) ' OR description ILIKE '%Notes :%')) OR (SELECT count(*) FROM public.pdc_email_operation_mapping_reviews_478 r JOIN public.vehicle_workshop_line_adjustments a ON a.source_operation_line_id=r.operation_line_id WHERE r.receipt_id='e7571359-c84c-493f-8376-d8384ea70b6f' AND r.status='pending' AND a.stage_code='OWNER_SUPPLIED_DOCUMENT')<>14 OR NOT EXISTS(SELECT 1 FROM public.vehicle_workshop_line_adjustments WHERE vehicle_id='99518513-5293-5619-a06e-9b4323754838' AND operation_code='OP13' AND estimated_hours=3 AND correction_origin='manual_operator') OR NOT EXISTS(SELECT 1 FROM public.vehicle_workshop_line_adjustments WHERE vehicle_id='99518513-5293-5619-a06e-9b4323754838' AND operation_code='OP19' AND estimated_hours=2 AND correction_origin='manual_operator') OR NOT EXISTS(SELECT 1 FROM public.pdc_authenticated_email_operation_lines WHERE vehicle_id='99518513-5293-5619-a06e-9b4323754838' AND operation_no='OP1' AND description LIKE '% CN %') OR NOT EXISTS(SELECT 1 FROM public.pdc_supervised_rule_versions v WHERE v.family_id='6620c922-1f16-4b17-8e02-a5402c15a5f7' AND v.version_no=2 AND v.estimated_hours=1.50 AND v.phrase_category='pre_delivery') THEN RAISE EXCEPTION 'PDC_482_POSTCONDITION_FAILED' USING errcode='55000';END IF;END $post$;
INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827032000','482_jobcard_header_only_all_lines',ARRAY['Persist Craig rule: use only the first OP header as the operation description','Persist and activate Craig standard: all Pre Delivery is 1.50 hours','Preserve immutable source evidence and project UID632 OP1-OP22 through header-only effective overlays','Keep all 22 visible; 14 unmapped lines remain under Unallocated - mapping review','Preserve later manual station/hour adjustments except the universal 1.50-hour Pre Delivery rule','Bind corrected paused runtime and keep all automatic writers disabled; Production untouched']);NOTIFY pgrst,'reload schema';COMMIT;
